typedef unsigned char u8; typedef signed char s8;
typedef unsigned short u16; typedef short s16;
typedef unsigned int u32; typedef int s32;
typedef long long s64; typedef unsigned long long u64;
struct Pair { int x;
int y; }; struct Off9 { int v[9]; };
struct TouchRec { u8 held;
u8 edge;
u8 x;
u8 y; };
struct OamAttr { u16 attr0;
u16 attr1;
u16 attr2;
u16 attr3; };
struct MgRecordDefaults { s32 v[5]; };
struct MgEntry { u16 id;
u16 pad; s32 sceneParam;
s32 scoringMode;
s32 scoreCap;
s32 ownRecords;
    MgRecordDefaults recordDefaults; s32 musicTrack;
s32 musicMode;
s32 level; };
struct dScMiniGm_c {
    u8 base[0x50]; s32 mSubBgScrollX; u8 mPageFlipped; u8 pad055[3];
    s32 mGroupBase;
s32 mStartLevel;
s32 unk_060;
s32 mGfxSlot;
s32 mGfxSlots[9];
    s32 mArrowBobPhase;
s32 mPrevPageTimer;
s32 mNextPageTimer;
s32 mExitTimer;
    s32 mIconBlinkPhase;
s32 mScrollDelay;
s32 unk_0a4;
s32 unk_0a8;
    u8 mExiting;
u8 pad0ad[3];
};
static_assert(sizeof(dScMiniGm_c)==0xb0);
static_assert(offsetof(dScMiniGm_c,mGfxSlots)==0x68);
static_assert(offsetof(dScMiniGm_c,mExiting)==0xac);
static_assert(sizeof(MgEntry)==0x34);

#define gMgSaveDirty (*Ptr<u8>(0x0209b300u))


#define gMgMenuPage (*Ptr<u8>(0x0209b304u))


#define gMgMenuRow (*Ptr<MgEntry>(0x0209b308u))


#define gMgMenuRowMid (*Ptr<MgRecordDefaults>(0x0209b31cu))


#define data_0209cae4 (*Ptr<u8>(0x0209cae4u))


#define data_0209caa0 ArrayRef<u32>(0x0209caa0u)


#define data_0209d454 (*Ptr<u8>(0x0209d454u))


#define data_0209d45c (*Ptr<u8>(0x0209d45cu))


#define data_0209d474 ArrayRef<short>(0x0209d474u)


#define data_0209d494 ArrayRef<short>(0x0209d494u)


#define data_0209e650 (*Ptr<int>(0x0209e650u))



#define data_0209f5f8 (*Ptr<u8>(0x0209f5f8u))


#define data_0209f61c (*Ptr<u8>(0x0209f61cu))


#define data_0208ee44 (*Ptr<int>(0x0208ee44u))

// local extern: this file needs a record-view spelling of one of the touch lanes (the ROM scales the slot in the addressing mode), which conflicts with PlayerInput.h; the header is not included and all five symbols are declared here.

#define gTouchHeld ArrayRef<TouchRec>(0x020a0de8u)

// local extern: see above.

#define gTouchEdge ArrayRef<u8>(0x020a0de9u)

// local extern: see above.

#define gTouchX ArrayRef<u8>(0x020a0deau)

// local extern: see above.

#define gTouchY ArrayRef<u8>(0x020a0debu)

// local extern: see above.

#define gActivePlayerSlot (*Ptr<u8>(0x020a0e40u))


#define data_020a0e5a ArrayRef<unsigned short>(0x020a0e5au)


/* ---- ov005 statics ---- */

#define sMiniGmBgFiles ArrayRef<int>(0x020c2260u)


#define sMiniGmRecordPos ArrayRef<Pair>(0x020c2280u)


#define sMiniGmBadgePos ArrayRef<Pair>(0x020c22c8u)


#define sMiniGmIconPalettes ArrayRef<u32>(0x020c2310u)


#define sMiniGmIconChars ArrayRef<int>(0x020c23a0u)


#define sMiniGmIconScreenOffsets (*Ptr<struct Off9>(0x020c2464u))
 /* 9-entry screen-offset table, not a matrix */
/* The menu rows (MgEntry, MgMenuRow.h), 36 of them: rows 0-23 are the first
   page of each tab, 24-35 the second. StartSceneFade(id, sceneParam, 0) opens the
   game, so sceneParam becomes the scene's fBase_c param1. Its low byte is the
   variant that dScMgBase_c::IsAltVariant tests. Six games are listed twice:
   Amida (rows 0/24), Snowball (6/34), Smartball (10/22), Coin (14/30), Panel
   (15/35) and Slot1 (17/33). Each first entry has low byte 0 and each second
   1, except Amida's row 24 with 2 (Amida's override asks for exactly 1).
   Sound's only entry (row 19) has 0, so its IsAltVariant branch is not
   reached from this menu. Seen in play: the two Snowballs start with param1
   0x0a00 and 0x2201. Bytes 1 and 2 each give every row a distinct number
   0..35. */

#define sMiniGmRows ArrayRef<const MgEntry>(0x020c24d8u)


#define sMiniGmSaveTable ArrayRef<int>(0x020c24dcu)


#define sMiniGmDigits ArrayRef<int>(0x020c2efcu)


#define sMiniGmRecordLabels ArrayRef<Ptr<void>>(0x020c2f4cu)




#define gMgGroupBase (*Ptr<int>(0x0208a170u))


#define gMgLastSelected ArrayRef<int>(0x0208a174u)



#define sMiniGmGroupBases ArrayRef<const int>(0x020c2250u)


#define sMiniGmGroupTabs ArrayRef<int>(0x020c2c28u)


#define sMiniGmPageArrows ArrayRef<int>(0x020c2ea4u)


#define sMiniGmNewBadge ArrayRef<int>(0x020c2f60u)


#define sMiniGmExitButton (*Ptr<int>(0x020c2e88u))


#define sMiniGmSavingCaption (*Ptr<int>(0x020c2f88u))


#define sMiniGmCaption (*Ptr<int>(0x020c2fccu))


#define data_0209b2fc (*Ptr<int>(0x0209b2fcu))


#define data_0209d4b8 (*Ptr<int>(0x0209d4b8u))

#define data_0209f1d8 (*Ptr<u8>(0x0209f1d8u))


